'use strict';
(()=>{
const D=window.ATLAS_DATA,slug=document.body.dataset.page,kind=document.body.dataset.kind,root=document.getElementById('interactive');
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('kk-KZ',{maximumFractionDigits:1}).format(n);const href=s=>s?`/${s}/`:'/';const current=D.pages.find(p=>p.slug===slug);
const buttons=(arr,attr,selected)=>arr.map(([v,label])=>`<button ${attr}="${esc(v)}" aria-pressed="${v===selected}">${esc(label)}</button>`).join('');
const field=(id,label,min,max,value,step=1,suffix='')=>`<label class="field" for="${id}"><span class="field-heading"><span>${label}</span><output id="${id}-out">${money(value)} ${suffix}</output></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}" data-suffix="${suffix}"></label>`;
function syncOutput(id){const el=$('#'+id),out=$('#'+id+'-out');if(out)out.value=money(Number(el.value))+' '+el.dataset.suffix;return Number(el.value)}
function source(id){const s=D.sources[id];if(!s)return;$('#source-detail').innerHTML=`<div class="source-id">${esc(id)} / БАСТАПҚЫ НЕГІЗ</div><h3>${esc(s.label)}</h3><p>Мақаладағы түсіндірме осы жарияланымға сүйенеді. Жарияланған жыл мен статистикалық кезең әрдайым бірдей емес.</p><p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Ресми дереккөзді тексеру</a></p><dl class="source-dates"><div><dt>Тексерілген күн</dt><dd>05.10.2026</dd></div><div><dt>Жарияланым және дерек кезеңі</dt><dd>Мақаладағы көрсеткішпен бірге берілген; бір-бірімен сәйкес келмеуі мүмкін.</dd></div></dl><p><small>Сандық дерек пен авторлық талдау мақалада ажыратылған. Бұл зерттеу күні; жарияланымның күні емес.</small></p>`;$('#source-dialog').showModal()}
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-open],[data-close],[data-source]');if(!b)return;if(b.dataset.source)source(b.dataset.source);else if(b.hasAttribute('data-close'))b.closest('dialog').close();else{const dlg=$('#'+b.dataset.open+'-dialog');dlg.showModal();if(b.dataset.open==='search'){search('');$('#search-input').focus()}}});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function search(q){const query=q.trim().toLocaleLowerCase('kk');let ps=D.pages.filter(p=>(p.title+' '+p.deck+' '+p.article.flatMap(a=>a.blocks.map(b=>b.text||b.rows?.flat().join(' '))).join(' ')).toLocaleLowerCase('kk').includes(query));$('#search-results').innerHTML=`<p style="margin-top:20px;color:#5a6b7b;font-size:.85rem">${ps.length} бөлім табылды</p>`+ps.map(p=>`<a class="search-result" href="${href(p.slug)}"><strong>${p.num} · ${esc(p.title)}</strong><small>${esc(p.deck)}</small></a>`).join('');if(!ps.length)$('#search-results').innerHTML+='<p>Басқа ұғымды немесе ел атауын енгізіңіз.</p>'}
$('#search-input').addEventListener('input',e=>search(e.target.value));document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();search('');$('#search-input').focus()}});
$('#reader-size')?.addEventListener('click',e=>{const on=document.body.classList.toggle('big-reading');e.currentTarget.setAttribute('aria-pressed',on);e.currentTarget.textContent=on?'Қалыпты мәтін':'Мәтінді үлкейту'});
window.addEventListener('scroll',()=>{const h=document.documentElement.scrollHeight-innerHeight;$('.read-progress').style.width=(h>0?scrollY/h*100:0)+'%'},{passive:true});

function atlas(){window.mountAtlas(root,D)}

const projects=[{id:'light',name:'Көшені жарықтандыру',cost:7.2,votes:85},{id:'park',name:'Мектеп ауласын көгалдандыру',cost:4.8,votes:67},{id:'water',name:'Су құбырын жаңарту',cost:9.5,votes:103},{id:'access',name:'Қолжетімді қоғамдық кеңістік',cost:3.6,votes:58},{id:'library',name:'Кітапхана және цифрлық оқу',cost:6.1,votes:77}];
function budget(){root.innerHTML=`<h2>Сіздің таңдауыңыз. Шектеулі бюджет.</h2><p>Жобаларды таңдап, қаржы шегін сақтаңыз. Барлық сандар — оқу мысалы.</p><div class="lab-columns"><div class="lab-form">${field('budget','Қолжетімді бюджет',5,40,20,.5,'млн ₸')}<div class="rows">${projects.map(p=>`<label class="project-option"><input type="checkbox" data-project="${p.id}"><div><strong>${p.name}</strong><small>${p.votes} оқу дауысы</small></div><b>${money(p.cost)} млн ₸</b></label>`).join('')}</div><button id="auto-budget" class="button primary" style="margin-top:20px">Дауыс ретімен бөлу</button></div><div class="lab-result" aria-live="polite" id="budget-result"></div></div>`;
function result(){const cap=syncOutput('budget'),selected=$$('[data-project]:checked',root).map(el=>projects.find(p=>p.id===el.dataset.project)),calc=window.AtlasAlgorithms.budget(cap,selected),total=calc.total,votes=calc.votes,rest=calc.remaining;$('#budget-result').innerHTML=`<div class="result-label">${rest<0?'БЮДЖЕТ ШЕГІ АСТЫ':'ҚАЛҒАН ҚАРАЖАТ'}</div><div class="big-number" style="${rest<0?'color:#ffb3a7':''}">${money(Math.abs(rest))} <span style="font-size:1.2rem">млн ₸</span></div><div class="meter"><span style="width:${Math.min(100,total/cap*100)}%;${rest<0?'background:#ffb3a7':''}"></span></div><p>${selected.length} жоба · ${money(total)} млн ₸<br>${votes} оқу дауысы қамтылды</p><div class="rows">${projects.filter(p=>!selected.includes(p)).map(p=>`<small>${p.name}: ${p.cost>rest?'қалған бюджетке сыймайды':'қаржы бар, таңдалмады'}</small>`).join('')}</div><p class="result-note">${rest<0?'Бір жобаны алып тастаңыз немесе бюджет шегін ұлғайтыңыз.':'Таңдау шектеуге сәйкес келеді. Бұл ресми бюджеттік шешім емес.'} Дауыс ретімен бөлу жобаларды дауыс саны бойынша қарайды, қалған ақшаға сыйғанын қосады. Бұл барлық жағдайда ең жоғары жиынтық дауысты табатын алгоритм емес.</p>`;return{budget:cap,total,remaining:rest,selected:selected.map(p=>p.id)}}
$('#budget').oninput=result;$$('[data-project]',root).forEach(el=>el.onchange=result);$('#auto-budget').onclick=()=>{const ids=window.AtlasAlgorithms.allocate(Number($('#budget').value),projects);$$('[data-project]',root).forEach(x=>x.checked=ids.includes(x.dataset.project));result()};result();root.readState=result;}

function license(){root.innerHTML=`<h2>Лицензия шартын модельдеңіз.</h2><p>Роялти, аванс, мерзім және шығын түсімге қалай әсер етеді?</p><div class="lab-columns"><div class="lab-form">${field('sales','Жылдық есептеу базасы',1,200,40,1,'млн ₸')}${field('royalty','Роялти мөлшерлемесі',1,15,5,.5,'%')}${field('years','Мерзім',1,10,3,1,'жыл')}${field('advance','Бір реттік аванс',0,20,2,.5,'млн ₸')}${field('expense','Жылдық қолдау шығыны',0,5,.5,.1,'млн ₸')}<label class="field">Пайдалану режимі<select id="exclusive"><option value="no">Айрықша емес лицензия</option><option value="yes">Айрықша лицензия</option></select></label></div><div class="lab-result" id="license-result" aria-live="polite"></div></div>`;
function result(){const sales=syncOutput('sales'),r=syncOutput('royalty'),years=syncOutput('years'),advance=syncOutput('advance'),expense=syncOutput('expense');const {gross,cost,net}=window.AtlasAlgorithms.license(sales,r,years,advance,expense);$('#license-result').innerHTML=`<div class="result-label">МОДЕЛЬДЕГІ ТАЗА ТҮСІМ</div><div class="big-number">${money(net)} <span style="font-size:1.2rem">млн ₸</span></div><div class="rows"><p>Жалпы түсім: <strong>${money(gross)} млн ₸</strong><br>Қолдау шығыны: <strong>${money(cost)} млн ₸</strong><br>Жылдық роялти: <strong>${money(sales*r/100)} млн ₸</strong></p></div><p>${$('#exclusive').value==='yes'?'Айрықша лицензияда басқа пайдаланушыларға рұқсат беру мүмкіндігі шартқа байланысты шектеледі.':'Айрықша емес лицензия бірнеше пайдаланушымен келісуге мүмкіндік бере алады; нақты шарт тексеріледі.'}</p><p class="result-note">Формула: аванс + жылдық база × роялти × жыл − жылдық қолдау шығыны × жыл. Сату өзгермейді деп алынды. Аванс роялтиден шегерілмейтін бөлек төлем ретінде модельденді. Салық, дисконттау және қорғау шығындары қамтылмаған. Бұл активтің нарықтық бағасы емес.</p>`;return{sales,royalty:r,years,gross,cost,net}}
$$('input,select',root).forEach(el=>el.addEventListener('input',result));result();root.readState=result;}

const roleData={
'Мәслихат':['Өкілді орган','Даму құжаттары мен жергілікті бюджетті бекіту, атқарушы органдар есептерін қарау.','Бюджетті бекіту сатып алу шартына қол қоюмен бірдей емес.','K1'],
'Әкімдік':['Атқарушы орган','Даму құжаттары мен бюджет жобасын әзірлеу және орындау, коммуналдық меншікті басқару.','Жоба әзірлеу мен бекіту әртүрлі құқықтық әрекеттер.','K1'],
'Қоғамдастық':['Қатысу нысаны','Жергілікті мәселелерді талқылау, заңда көзделген келісу және мониторинг.','Қоғамдастық келісімі мәслихаттың бюджетті бекітуін алмастырмайды.','K2'],
'Үкімет':['Ұлттық атқарушы деңгей','Заңдарды іске асыру және атқарушы органдар жұмысын ұйымдастыру.','Жергілікті мәселе автоматты түрде орталық органның күнделікті шешіміне жатпайды.','K1']};
function powers(){root.innerHTML=`<h2>Бір шешімдегі төрт рөл.</h2><p>Органды таңдап, шешімнің қай кезеңіне жауап беретінін қараңыз.</p><div class="tabs" id="role-tabs">${buttons(Object.keys(roleData).map(x=>[x,x]),'data-role','Мәслихат')}</div><div id="role-detail" class="lab-result" aria-live="polite"></div>`;
function show(name){const r=roleData[name];$('#role-detail').innerHTML=`<div class="eyebrow">${r[0]}</div><h3>${name}</h3><p>${r[1]}</p><div class="feedback">${r[2]}</div><p class="result-note">Конституциялық негіз және салалық заң бірге қаралады. Нақты іс үшін аумақ, мүлік деңгейі және арнайы өкілеттік тексеріледі. <button class="cite" data-source="${r[3]}">${r[3]}</button></p>`}
root.onclick=e=>{const b=e.target.closest('[data-role]');if(!b)return;$$('[data-role]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));show(b.dataset.role)};show('Мәслихат')}

const journeySets={
'estonia':[['Дерек енгізу','Тұрғын мәліметін қызметке береді. Қай дерек шынымен қажет екенін анықтау алғашқы қадам.'],['Өкілетті тексеру','Деректі басқа органға берудің заңды негізі мен қызмет мақсаты тексеріледі.'],['Қауіпсіз алмасу','Тәуелсіз жүйелер тиісті сұрау арқылы алмасады. Бұл жалғыз ортақ дерекқор дегенді білдірмейді.'],['Нәтиже және түзету','Қызмет аяқталады; қате деректі түзету жолы мен жауапты орган көрінеді.']],
'paris':[['Ұсыныс','Тұрғын қажеттілікті сипаттайды. Ол қала құзыретіне және жоба талаптарына сай тексеріледі.'],['Таңдау','Ұсыныстарға дауыс беріледі. Таңдалған жоба әлі аяқталған жоба емес.'],['Орындау','Жобалау, сатып алу, жұмыс және қабылдау кезеңдері бөлек бақыланады.'],['Қоғамдық нәтиже','Объект қолданысқа беріліп, күтім мен қызмет сапасы бағаланады.']],
'accountability':[['Шешім','Шешім қабылдаған орган, өкілеттік және құжат анықталады.'],['Орындалу','Шарт, қабылдау және бюджет шығыстарының дәлелі салыстырылады.'],['Есеп','Орындаушы ресурстың жұмсалуын және нақты қызмет нәтижесін түсіндіреді.'],['Қорғану','Құқықтық бұзушылық пен басымдыққа қатысты келіспеушілік ажыратылады; тиісті шағым жолы таңдалады.']],
'public-project':[['Құзырет пен бюджет','Мәселе, өкілеттік, қаржы және пайдаланушының қажеттілігі белгіленеді.'],['Сатып алу шарты','Код, дерек, құқық, жаңарту және жеткізушіні ауыстыру шарттары анықталады.'],['Қабылдау','Тек экранның болуы емес, функция, қолжетімділік және дерек экспорты тексеріледі.'],['Ұзақ басқару','Жаңарту, қолдау шығыны, құқықтарды пайдалану және қоғамдық есеп жалғасады.']]};
const defaultJourney=[['Мәселе','Қажеттілік, мекенжай және күтілетін нәтиже анықталады.'],['Құзырет','Объектінің меншік деңгейі, жауапты орган және қаржы көзі тексеріледі.'],['Шешім','Әзірлеу, қоғамдастықпен келісу және бюджет бекіту өз рәсімімен жүреді.'],['Орындау','Сатып алу, қабылдау және қызмет нәтижесі бойынша есеп беріледі.']];
function journey(){const steps=journeySets[slug]||defaultJourney;root.innerHTML='<h2>Шешімнің жолын ашыңыз.</h2><div class="step-grid">'+steps.map((s,i)=>`<button data-step="${i}" aria-pressed="${i===0}"><small>0${i+1}</small>${s[0]}</button>`).join('')+'</div><div id="step-detail" class="lab-result" aria-live="polite"></div>';function show(i){$('#step-detail').innerHTML=`<div class="eyebrow">КЕЗЕҢ ${i+1} / ${steps.length}</div><h3>${steps[i][0]}</h3><p>${steps[i][1]}</p><p class="result-note">Бұл — механизмді түсіндіретін оқу маршруты. Нақты рәсім елге, объектіге және құқықтық режимге байланысты.</p>`}root.onclick=e=>{const b=e.target.closest('[data-step]');if(!b)return;$$('[data-step]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));show(Number(b.dataset.step))};show(0)}

function finance(){root.innerHTML=`<h2>Кіріс көзін өзгертіп көріңіз.</h2><p>Өз кірісі мен трансферттің бюджеттің құрылымына әсері. Сандар — оқу мысалы.</p><div class="lab-columns"><div class="lab-form">${field('own-income','Меншікті кіріс',0,100,25,1,'млн ₸')}${field('transfer','Трансферт',0,200,75,1,'млн ₸')}${field('mandatory','Міндетті шығыс',0,100,60,1,'млн ₸')}</div><div id="finance-result" class="lab-result" aria-live="polite"></div></div>`;function result(){const own=syncOutput('own-income'),t=syncOutput('transfer'),m=syncOutput('mandatory'),calc=window.AtlasAlgorithms.finance(own,t,m),total=calc.total,share=calc.share;$('#finance-result').innerHTML=`<div class="result-label">МЕНШІКТІ КІРІС ҮЛЕСІ</div><div class="big-number">${total?money(share)+'%':'Кіріс жоқ'}</div><div class="meter"><span style="width:${share}%"></span></div><p>Жалпы кіріс: ${money(total)} млн ₸<br>Міндетті шығыстан кейін: ${money(total-m)} млн ₸</p><p class="result-note">Меншікті кіріс үлесі = меншікті кіріс / жалпы кіріс × 100%. Қалған соманың бәрі еркін жұмсалады деп алынбайды: нысаналы трансферт пен басқа міндеттемелер болуы мүмкін. Трансферт алу өздігінен тиімсіздік емес, аумақтарды теңестіру құралы болуы мүмкін.</p>`}$$('input',root).forEach(x=>x.oninput=result);result()}

const models={
'Германия':['Муниципалитет','Жергілікті істерді өз жауапкершілігімен реттеудің конституциялық кепілдігі.','Қаржылық дербестікке, оның ішінде тиісті салық көздеріне кепілдік.','Негізгі заң, 28-бап.','G1'],
'Швейцария':['Муниципалитет және кантон','Муниципалдық дербестік кантондық құқық шеңберінде.','Бір елдің ішінде жергілікті ережелердің айырмасы болуы мүмкін.','Федерализм: ұлттық, кантондық және муниципалдық деңгей.','G2'],
'Дания':['Жергілікті шығыс','2023 жылғы жергілікті шығыс үлесі: 64,3%.','Шығыс үлесі салық еркіндігінің толық өлшемі емес.','OECD 2025 есебіндегі 2023 дерегі.','G3'],
'Швеция':['Жергілікті шығыс','2023 жылғы жергілікті шығыс үлесі: 50,7%.','Қызметтердің бөлінуі ескерілмей тиімділік рейтингі жасалмайды.','OECD 2025 есебіндегі 2023 дерегі.','G3'],
'Сингапур':['Қалалық мемлекет','JTC мен GovTech-тің аудандық цифрлық инфрақұрылымы.','Punggol: 20 мыңнан астам сенсор; бұл энергия үнемінің пайызы емес.','2026 жылғы ресми хабарлама.','G18'],
'Эстония':['Ұлттық цифрлық инфрақұрылым','Онлайн қолжетімділік пен жүйелердің өзара алмасуы.','Қолжетімді қызмет пен оны пайдаланған тұрғынның үлесі бөлек.','2024 ресми таныстырылым және X-Road түсіндірмесі.','G13']};
function compare(){const ns=Object.keys(models);root.innerHTML='<h2>Өлшемді сақтап салыстырыңыз.</h2><p>Институт, қаржы және деректің шегін екі жақтан қараңыз.</p><div class="compare-grid">'+[0,1].map(i=>`<div class="compare-item"><label class="field">${i?'Екінші':'Бірінші'} модель<select id="country-${i}">${ns.map((s,j)=>`<option ${j===i?'selected':''}>${s}</option>`).join('')}</select></label><div id="compare-${i}"></div></div>`).join('')+'</div><p class="result-note">Кесте сипаттамалық салыстыруға арналған. Салық дербестігі, шығыс үлесі және цифрлық инфрақұрылым бірдей көрсеткіш емес; бір жалпы «үздік ел» баллы есептелмейді.</p>';function result(){[0,1].forEach(i=>{const m=models[$('#country-'+i).value];$('#compare-'+i).innerHTML=`<dl><dt>Деңгей</dt><dd>${m[0]}</dd><dt>Негізгі ерекшелік</dt><dd>${m[1]}</dd><dt>Маңызды шектеу</dt><dd>${m[2]}</dd><dt>Дерек негізі</dt><dd>${m[3]} <button class="cite" data-source="${m[4]}">${m[4]}</button></dd></dl>`})}$$('select',root).forEach(x=>x.onchange=result);result()}

const quizSets={
'india':[['AI хаттама дайындады. Келесі қадам қандай?',['Автоматты түрде ресми шешім деп жариялау','Жауапты қызметкердің тексеруі және бекітуі','Жиын өткізудің қажеті жоқ'],1,'Үндістан кейсінде соңғы хаттаманы жауапты қызметкерлер тексеріп, бекітеді. Өңделген файл қабылданған шешімге тең емес.'],['357 020 хаттама нені көрсетеді?',['Құжат өңдеу көлемін','Орындалған жобалардың санын','Қате жоқ екенін'],0,'Көлем енгізудің ауқымын көрсетеді. Дәлдік, түзету және орындалу бөлек өлшенеді.']],
'heritage':[['Мәдени өрнек интернетте жарияланған. Не тексеріледі?',['Интернетте болса, бәріне рұқсат','Құқық, келісім, контекст және атрибуция','Тек суреттің көлемі'],1,'Қолжетімділік коммерциялық пайдалану рұқсатын автоматты бермейді. Құқықтық режим мен қауымдық келісім бөлек қаралады.'],['Шарттың қабылдануы нені білдіреді?',['Барлық елде сол күні күшіне енді','Қабылдау мен күшіне ену шарттары бөлек','Барлық фольклорға жаңа авторлық құқық берілді'],1,'2024 шарттың қабылдануы оның әр елде қолданылатынын дәлелдемейді; күшіне ену және ұлттық қолдану бөлек тексеріледі.']],
'ai-copyright':[['Промпт жазу адам авторлығын автоматты дәлелдей ме?',['Әрдайым дәлелдейді','АҚШ қорытындысы бойынша жай промпт өздігінен жеткіліксіз','AI қолданылса, адам еңбегі ешқашан қорғалмайды'],1,'Адамның шығармашылық элементті анықтауы, өңдеуі және орналастыруы маңызды болуы мүмкін. Бұл АҚШ ұстанымы.'],['AI құралының шарты нені алмастырмайды?',['Үшінші тұлғаның құқықтарын тексеруді','Пайдаланушы интерфейсін','Файл атауын'],0,'Қызмет шартындағы рұқсат үшінші тұлғаның құқықтарын автоматты заңдастырмайды.']],
'ai-patents':[['2026 жылғы Emotional Perception шешімі патент берді ме?',['Патент автоматты берілді','Іс қалған талаптарды қарауға қайта жіберілді','AI заңды өнертапқыш болып танылды'],1,'Алғашқы техникалық сипат шегінен өту жаңалық, өнертапқыштық деңгей және басқа талаптарды алмастырмайды.'],['GenAI патент отбасы нені білдіреді?',['Дайын сатылатын өнім','Байланысты патент өтінімдерінің тобы','Міндетті түрде берілген бір патент'],1,'Жарияланған отбасы, берілген патент және коммерциялық өнім саны бөлек көрсеткіштер.']]};
function quiz(){const qs=quizSets[slug]||quizSets['ai-patents'];let index=0,score=0,answered=false;function render(){const q=qs[index];root.innerHTML=`<div class="eyebrow">СЦЕНАРИЙ ${index+1} / ${qs.length}</div><h2>${q[0]}</h2><div class="quiz-answers">${q[1].map((x,i)=>`<button data-answer="${i}">${x}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><button id="quiz-next" class="button primary" hidden style="margin-top:22px">${index===qs.length-1?'Қайта көру':'Келесі сұрақ'}</button>`;$$('[data-answer]',root).forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const correct=Number(b.dataset.answer)===q[2];if(correct)score++;b.classList.add('selected');$$('[data-answer]',root).forEach(x=>x.disabled=true);$('#quiz-feedback').innerHTML=`<div class="feedback"><strong>${correct?'Дұрыс.':'Дұрыс жауап: '+q[1][q[2]]+'.'}</strong><p style="margin:10px 0 0">${q[3]}</p></div>${index===qs.length-1?`<p style="margin-top:20px">Нәтиже: ${score} / ${qs.length}. Бұл оқу жаттығуы.</p>`:''}`;$('#quiz-next').hidden=false});$('#quiz-next').onclick=()=>{index++;if(index===qs.length){index=0;score=0}answered=false;render()}}render()}

function ip(){const sets={
'Авторлық туынды':['Туындының нақты нысаны','Мәтін, код, сурет немесе музыкадағы шығармашылық өрнекті талдаңыз. Идея мен оның нақты берілуі ажыратылады.','Автор, шарттағы құқық иесі және пайдаланушы бөлек көрсетіледі.'],
'Техникалық шешім':['Ықтимал патент және құпия','Техникалық шешімнің жаңалығы мен өзге талаптар сараптама арқылы қаралады. Өз патентінің болуы әрекет ету еркіндігін автоматты бермейді.','Жариялау сәті, қызметтік нәтиже және қорғау аумағы маңызды.'],
'Бренд және өңірлік атау':['Тауар белгісі не географиялық көрсеткіш','Бренд белгілі құқық иесінің тауарын ажыратады. Географиялық көрсеткіш өңір, өнім және белгіленген шарт арасындағы байланысты қорғайды.','Құқық иесі, өндірушілердің қатысуы және сапа бақылауы тексеріледі.'],
'Ашық код':['Лицензия және контент режимі','Ашық код қайта қолдануға мүмкіндік беруі мүмкін, бірақ нақты лицензия шартын сақтау керек. Код лицензиясы тұрғынның жеке деректерін тарату рұқсаты емес.','Өзгеріс, тарату, атрибуция және құжаттама шарттары бөлек тексеріледі.']};root.innerHTML='<h2>Объектінің құқықтық қабатын таңдаңыз.</h2><p>Бір өнімге бірнеше құқық режимі қатар қолданылуы мүмкін.</p><div class="tabs">'+buttons(Object.keys(sets).map(s=>[s,s]),'data-object','Авторлық туынды')+'</div><div id="ip-detail" class="lab-result" aria-live="polite"></div>';function show(s){const v=sets[s];$('#ip-detail').innerHTML=`<div class="eyebrow">${s}</div><h3>${v[0]}</h3><p>${v[1]}</p><div class="feedback">${v[2]}</div><p class="result-note">Бұл объектілерді ажыратуға арналған навигатор. Нақты құқықтың тиесілігі мен қорғау мүмкіндігі елге, шартқа және құжаттарға байланысты.</p>`}root.onclick=e=>{const b=e.target.closest('[data-object]');if(!b)return;$$('[data-object]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));show(b.dataset.object)};show('Авторлық туынды')}

const events=[['2023-12-20','DABUS','AI өнертапқыш ретінде көрсетіле алмайды деген Ұлыбритания шешімі.','ai-patents','G25'],['2024-03-18','OmaStadi','Хельсинкидегі 2024 дауыс беруі: 41 962 қатысушы, 8,8 млн еуро.','nordic','G12'],['2025-01-29','AI және автор','АҚШ Copyright Office: адам шығармашылығы мен AI көмегі туралы қорытынды.','ai-copyright','G24'],['2026-02-11','AI патенті','Emotional Perception AI ісі қалған талаптарды қарауға қайта жіберілді.','ai-patents','G26'],['2026-07-09','Цифрлық егіз','Punggol инфрақұрылымы және Panasonic-пен сынақ серіктестігі.','digital-city','G18'],['2026-07-14','GenAI патенттері','WIPO 2025 жылға дейінгі жарияланған патент отбасылары дерегін жаңартты.','ai-patents','G23'],['2026-08-12','Ауылдық AI','Үндістан: жоспарлау, төлем және SabhaSaar туралы парламенттік жауап.','india','G15'],['2026-08-27','Нью-Йорк','2026 қатысу бюджетінің жеңімпаздары туралы хабарлама.','new-york','G8'],['2026-09-29','GII 2026','139 экономиканы қамтитын жаңа инновация индексі жарияланды.','innovation','G21']];
function timeline(){let evs=slug==='porto-alegre'?[['1989–1996','Тарихи инфрақұрылым','Су және кәріз қамтуының өсуі сипатталған. Бұл тарихи бақылау, бір ғана себептің дәлелі емес.','porto-alegre','G10'],['2025-08-13','18 мың қатысушы','Қала қатысу бюджетіне 18 мың адам қатысқанын хабарлады. Тарихи дерекпен бір кезеңге біріктірілмейді.','porto-alegre','G11']]:events;root.innerHTML='<h2>Оқиғаны уақытынан ажыратпаңыз.</h2><div class="timeline">'+evs.map((v,i)=>`<button data-event="${i}" aria-pressed="${i===evs.length-1}"><span>${v[0]}</span>${v[1]}</button>`).join('')+'</div><div id="event-detail" class="lab-result" aria-live="polite"></div>';function show(i){const v=evs[i];$('#event-detail').innerHTML=`<div class="eyebrow">${v[0]}</div><h3>${v[1]}</h3><p>${v[2]}</p><a class="button primary" href="${href(v[3])}">Толық талдауды оқу</a><p class="result-note">Оқиға немесе жариялау күні көрсетілді. Мәліметтің есептік кезеңі мақалада бөлек беріледі. <button class="cite" data-source="${v[4]}">${v[4]}</button></p>`}root.onclick=e=>{const b=e.target.closest('[data-event]');if(!b)return;$$('[data-event]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));show(Number(b.dataset.event))};show(evs.length-1)}

const stats={
'nyc':{title:'Нью-Йорк: дауыс арнасы',unit:'дауыс',period:'2026',src:'G9',rows:[['Қағаз',122380],['Цифрлық',12038]],note:'Жалпы: 134 418. Қағаз үлесі ≈ 91,0%, цифрлық үлесі ≈ 9,0% — осы сандардан есептелді. Бұл барлық тұрғынның цифрлық сауат көрсеткіші емес.'},
'fiscal':{title:'Жергілікті шығыс үлесі',unit:'%',period:'2023 · OECD 2025 есебі',src:'G3',rows:[['Дания',64.3],['Швеция',50.7]],note:'Жалпы мемлекеттік шығыстағы жергілікті деңгей үлесі. Бұл салық дербестігі немесе қызмет сапасының рейтингі емес.'},
'patents':{title:'Әлемдік патент өтінімдері',unit:'млн өтінім',period:'2024 · WIPO 2025 жарияланымы',src:'G20',rows:[['Барлық кеңселер',3.7]],note:'2023 жылмен салыстырғандағы өсім: 4,9%. Өтінім саны бірегей өнім немесе берілген патент санына тең емес.'},
'genai':{title:'GenAI патент отбасылары',unit:'мың жарияланған отбасы',period:'2023 және 2025 · WIPO 2026 жаңартуы',src:'G23',rows:[['2023 · шамамен',14],['2025 · одан астам',37.8]],note:'Екі көрсеткіштің дөңгелектеу және «одан астам» сипаты сақталды. Берілген патент пен дайын AI өнімі ретінде есептелмейді.'}}
function statistics(){let active=slug==='new-york'?'nyc':'patents';root.innerHTML='<h2>Санды бірлігімен бірге оқыңыз.</h2><div class="tabs">'+buttons([['nyc','Дауыс арналары'],['fiscal','Шығыс үлесі'],['patents','Патент өтінімдері'],['genai','GenAI отбасылары']],'data-stat',active)+'</div><div id="stat-result" aria-live="polite"></div>';function show(k){const s=stats[k],max=Math.max(...s.rows.map(x=>x[1]));$('#stat-result').innerHTML=`<div class="eyebrow">${s.period}</div><h3>${s.title}</h3><p>Өлшем: ${s.unit}</p><div class="stat-bars">${s.rows.map(([label,val])=>`<div><div class="stat-bar-head"><span>${label}</span><b>${money(val)}</b></div><div class="stat-bar"><div style="width:${val/max*100}%"></div></div></div>`).join('')}</div><div class="table-scroll"><table class="stat-table"><thead><tr><th>Көрсеткіш</th><th>${s.unit}</th></tr></thead><tbody>${s.rows.map(([l,v])=>`<tr><td>${l}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table></div><p class="result-note">${s.note} <button class="cite" data-source="${s.src}">${s.src}</button></p>`}root.onclick=e=>{const b=e.target.closest('[data-stat]');if(!b)return;active=b.dataset.stat;$$('[data-stat]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));show(active)};show(active)}

function city(){root.innerHTML=`<h2>Ресурс пен әсерді байланыстырыңыз.</h2><p>Үнемдеу сценарийі: бастапқы шығынды, қолдану үлесін және әсерді өзгертіңіз.</p><div class="lab-columns"><div class="lab-form">${field('base','Бастапқы жылдық шығын',10,200,80,1,'млн ₸')}${field('adopt','Шешімді қолдану үлесі',0,100,60,5,'%')}${field('effect','Қолданылған бөліктегі үнем',0,40,15,1,'%')}</div><div id="city-result" class="lab-result" aria-live="polite"></div></div>`;function result(){const base=syncOutput('base'),adopt=syncOutput('adopt'),effect=syncOutput('effect'),calc=window.AtlasAlgorithms.savings(base,adopt,effect),saved=calc.saved,left=calc.left;$('#city-result').innerHTML=`<div class="result-label">МОДЕЛЬДЕГІ ЖЫЛДЫҚ ҮНЕМ</div><div class="big-number">${money(saved)} <span style="font-size:1.2rem">млн ₸</span></div><div class="city-visual" aria-label="Бастапқы және кейінгі шығынды салыстыру"><div class="city-bar" style="height:145px"><span>Бастапқы</span></div><div class="city-bar" style="height:${base?left/base*145:0}px;background:linear-gradient(0deg,#946027,#f0bd74)"><span>Сценарий</span></div></div><p style="margin-top:18px">${money(base)} млн ₸ → ${money(left)} млн ₸</p><p class="result-note">Формула: шығын × қолдану үлесі × үнем үлесі. Барлық кіріс — оқу параметрі. Бұл Punggol, Кейптаун немесе басқа қаланың өлшенген үнемі емес. Енгізу, қолдау және инфрақұрылым шығыны қамтылмаған; нақты тиімділік үшін олар қосымша қажет.</p>`}$$('input',root).forEach(x=>x.oninput=result);result()}

function sources(){root.innerHTML='<h2>77 бастапқы негіз.</h2><p>Қазақстан және әлемдік зерттеу. Атауы, орган немесе тақырып бойынша іздеңіз.</p><label class="field">Дереккөзді іздеу<input type="search" id="source-search" placeholder="WIPO, бюджет, Конституция…"></label><div class="tabs">'+buttons([['all','Барлығы'],['K','Қазақстан'],['G','Әлем']],'data-source-filter','all')+'</div><p id="source-count"></p><div id="source-list" class="source-grid"></div>';let prefix='all';function render(){const q=$('#source-search').value.toLowerCase(),ss=Object.values(D.sources).filter(s=>(prefix==='all'||s.id.startsWith(prefix))&&s.label.toLowerCase().includes(q));$('#source-count').textContent=ss.length+' дереккөз';$('#source-list').innerHTML=ss.map(s=>`<button data-source="${s.id}"><span>${s.id}</span>${esc(s.label)}</button>`).join('')||'<div class="empty">Сәйкес дереккөз жоқ. Іздеу сөзін өзгертіңіз.</div>'}$('#source-search').oninput=render;root.addEventListener('click',e=>{const b=e.target.closest('[data-source-filter]');if(!b)return;prefix=b.dataset.sourceFilter;$$('[data-source-filter]',root).forEach(x=>x.setAttribute('aria-pressed',x===b));render()});render()}
if(root){({home:atlas,atlas,timeline,powers,journey,finance,compare,budget,license,quiz,stats:statistics,ip,city,sources}[kind]||journey)()}
// Structured tools share the same visible state. Unsupported browsers keep all UI available.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
register({name:'search_atlas_pages',title:'Атластан іздеу',description:'Read matching full article titles and routes without changing state.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(v){if(!v||typeof v.query!=='string'||v.query.length>200)throw new Error('Invalid query');const q=v.query.toLowerCase();return D.pages.filter(p=>(p.title+' '+p.deck).toLowerCase().includes(q)).map(p=>({title:p.title,url:href(p.slug)}))}});
if(kind==='budget')register({name:'configure_learning_budget',title:'Оқу бюджетін өзгерту',description:'Set demonstration budget and projects in the visible learning laboratory; does not allocate real funds.',inputSchema:{type:'object',properties:{budget:{type:'number',minimum:5,maximum:40},projects:{type:'array',items:{type:'string',enum:projects.map(p=>p.id)},uniqueItems:true}},required:['budget','projects'],additionalProperties:false},annotations:{readOnlyHint:false},execute(v){if(!v||!Number.isFinite(v.budget)||v.budget<5||v.budget>40||!Array.isArray(v.projects)||v.projects.some(id=>!projects.some(p=>p.id===id)))throw new Error('Invalid learning parameters');$('#budget').value=v.budget;$$('[data-project]',root).forEach(x=>x.checked=v.projects.includes(x.dataset.project));return root.readState()}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
